package ma.adria.assistantservice.service;
import org.springframework.stereotype.Service;import org.springframework.ai.chat.client.ChatClient;import org.springframework.ai.tool.ToolCallbackProvider;
@Service public class AssistantService {private final ChatClient chat;public AssistantService(ChatClient.Builder builder,ToolCallbackProvider tools){chat=builder.defaultSystem("Assistant bancaire. Utilise uniquement les outils pour les données bancaires. Demande une confirmation explicite avant une écriture, avec montant, devise et comptes. Ne prétends jamais qu'une opération a réussi sans réponse de l'outil. Ne révèle pas de secrets.").defaultToolCallbacks(tools).build();}public String ask(String message){if(message==null||message.isBlank()||message.length()>8000)throw new IllegalArgumentException("Message invalide");return chat.prompt().user(message).call().content();}}
